const { test, expect } = require('@playwright/test');
const { createApiContext, apiGet, apiPost, WP_URL } = require('../fixtures/wp-api');

// === REST API: GET /import/detect ===
test.describe('REST API — GET /import/detect', () => {
  let api;

  test.beforeAll(async () => {
    api = await createApiContext();
  });

  test.afterAll(async () => {
    await api.dispose();
  });

  test('detect returns 200 with detected and snapshots keys', async () => {
    const resp = await api.get('/wp-json/thinkrank/v1/import/detect');
    expect(resp.status()).toBe(200);
    const body = await resp.json();
    expect(body).toHaveProperty('detected');
    expect(body).toHaveProperty('snapshots');
    expect(typeof body.detected).toBe('object');
    expect(typeof body.snapshots).toBe('object');
  });

  test('detect — unauthenticated request returns 401 or 403', async ({ request }) => {
    const resp = await request.get(`${WP_URL}/wp-json/thinkrank/v1/import/detect`);
    expect([401, 403]).toContain(resp.status());
  });

  test('detect — detected object entries have expected shape when plugins found', async () => {
    const resp = await api.get('/wp-json/thinkrank/v1/import/detect');
    const body = await resp.json();
    for (const [slug, info] of Object.entries(body.detected)) {
      expect(['yoast', 'rankmath', 'seopress', 'aioseo']).toContain(slug);
      expect(info).toHaveProperty('plugin');
      expect(info).toHaveProperty('plugin_name');
      expect(info).toHaveProperty('counts');
      expect(info).toHaveProperty('total');
    }
  });
});

