// === REST API: POST /import/migrate ===
test.describe('REST API — POST /import/migrate', () => {
  let api;

  test.beforeAll(async () => {
    api = await createApiContext();
  });

  test.afterAll(async () => {
    await api.dispose();
  });

  test('migrate without completed snapshot returns error status', async () => {
    // Migrating a plugin that has never been exported should return error
    const resp = await api.post('/wp-json/thinkrank/v1/import/migrate', {
      data: { plugin: 'seopress', type: 'postmeta', page: 1 },
    });
    expect(resp.status()).toBe(200); // 200 with error body or with complete body
    const body = await resp.json();
    // If no snapshot exists, it should either report error or complete with 0 records
    expect(['error', 'complete', 'processing']).toContain(body.status);
  });

  test('migrate — missing required plugin param returns 400', async () => {
    const resp = await api.post('/wp-json/thinkrank/v1/import/migrate', {
      data: { type: 'postmeta', page: 1 },
    });
    expect(resp.status()).toBe(400);
  });

  test('migrate — missing required type param returns 400', async () => {
    const resp = await api.post('/wp-json/thinkrank/v1/import/migrate', {
      data: { plugin: 'yoast', page: 1 },
    });
    expect(resp.status()).toBe(400);
  });

  test('migrate — missing required page param returns 400', async () => {
    const resp = await api.post('/wp-json/thinkrank/v1/import/migrate', {
      data: { plugin: 'yoast', type: 'postmeta' },
    });
    expect(resp.status()).toBe(400);
  });

  test('migrate — invalid plugin is rejected (400) or returns error status', async () => {
    // Same enum validation note — WP may not enforce enum without validate_callback.
    const resp = await api.post('/wp-json/thinkrank/v1/import/migrate', {
      data: { plugin: 'not-a-plugin', type: 'postmeta', page: 1 },
    });
    expect([400, 200]).toContain(resp.status());
    if (resp.status() === 200) {
      const body = await resp.json();
      // Should be error (no snapshot found) or complete with 0 records
      expect(['error', 'complete']).toContain(body.status);
    }
  });

  test('migrate — unauthenticated POST returns 401 or 403', async ({ request }) => {
    const resp = await request.post(`${WP_URL}/wp-json/thinkrank/v1/import/migrate`, {
      data: { plugin: 'yoast', type: 'postmeta', page: 1 },
    });
    expect([401, 403]).toContain(resp.status());
  });

  test('migrate after successful export returns processed/skipped counts', async () => {
    // First export yoast settings to create a complete snapshot
    const exportResp = await api.post('/wp-json/thinkrank/v1/import/export', {
      data: { plugin: 'yoast', type: 'settings', page: 1, is_last_type: true },
    });
    expect(exportResp.status()).toBe(200);

    // Manually finalize: export with is_last_type to mark complete
    // (settings type auto-completes the manifest via finalize_export)
    // Now try to migrate settings
    const migrateResp = await api.post('/wp-json/thinkrank/v1/import/migrate', {
      data: { plugin: 'yoast', type: 'settings', page: 1, is_last_type: true },
    });
    const body = await migrateResp.json();
    // Response should have processed/skipped counts (could be 0 if snapshot not finalized)
    if (body.status !== 'error') {
      expect(body).toHaveProperty('processed');
      expect(body).toHaveProperty('skipped');
      expect(typeof body.processed).toBe('number');
      expect(typeof body.skipped).toBe('number');
    }
  });
});

