// === ADMIN PAGE: Import / Export ===
test.describe('Admin page — Import / Export (thinkrank-import-export)', () => {
  test('page loads without PHP fatal or parse error', async ({ page }) => {
    const jsErrors = [];
    page.on('console', msg => { if (msg.type() === 'error') jsErrors.push(msg.text()); });
    page.on('pageerror', e => jsErrors.push(e.message));

    const resp = await page.goto(`${WP_URL}/wp-admin/admin.php?page=thinkrank-import-export`);
    expect(resp.status()).not.toBe(500);

    const body = await page.textContent('body');
    expect(body).not.toContain('Fatal error');
    expect(body).not.toContain('Parse error');
    expect(body).not.toContain('WordPress database error');

    const critical = jsErrors.filter(e =>
      e.includes('thinkrank') || e.includes('ThinkRank') || e.toLowerCase().includes('uncaught')
    );
    expect(critical).toHaveLength(0);
  });

  test('page renders Import SEO Data heading', async ({ page }) => {
    await page.goto(`${WP_URL}/wp-admin/admin.php?page=thinkrank-import-export`);
    await page.waitForLoadState('networkidle');

    const heading = page.locator('h2, h1').filter({ hasText: 'Import SEO Data' });
    await expect(heading).toBeVisible({ timeout: 15_000 });
  });

  test('page shows loading spinner then resolves', async ({ page }) => {
    await page.goto(`${WP_URL}/wp-admin/admin.php?page=thinkrank-import-export`);
    // After networkidle the spinner should be gone
    await page.waitForLoadState('networkidle');
    const spinner = page.locator('.components-spinner');
    // Spinner should have disappeared (or never appeared if load was fast)
    const spinnerCount = await spinner.count();
    if (spinnerCount > 0) {
      await expect(spinner.first()).not.toBeVisible({ timeout: 10_000 });
    }
  });

  test('page shows plugin cards or empty notice after detection', async ({ page }) => {
    await page.goto(`${WP_URL}/wp-admin/admin.php?page=thinkrank-import-export`);
    await page.waitForLoadState('networkidle');

    // Either a plugin card or an info notice about no data found
    const cards = page.locator('.thinkrank-import-export-tab .components-notice, .thinkrank-import-export-tab [class*="plugin-card"], .thinkrank-import-export-tab h3');
    const count = await cards.count();
    expect(count).toBeGreaterThanOrEqual(0); // Page rendered content
  });

  test('Import / Export appears in ThinkRank admin submenu', async ({ page }) => {
    await page.goto(`${WP_URL}/wp-admin/admin.php?page=thinkrank`);
    await page.waitForLoadState('networkidle');
    const importLink = page.locator('a[href*="thinkrank-import-export"]');
    await expect(importLink).toBeVisible({ timeout: 10_000 });
  });
});

