// === METABOX: Robots Meta Override ===
test.describe('Metabox — Robots Meta (new JSON structure)', () => {
  let api;

  test.beforeAll(async () => {
    api = await createApiContext();
  });

  test.afterAll(async () => {
    await api.dispose();
  });

  test('_thinkrank_robots_meta_enabled meta key is registered in REST', async () => {
    // GET /wp/v2/posts — look at meta keys schema to confirm registration
    const resp = await api.get('/wp-json/wp/v2/posts?per_page=1');
    expect([200, 404]).toContain(resp.status());
    // Meta registration is confirmed if no PHP error occurs on page load
  });

  test('frontend robots tag contains index/follow by default for a published post', async ({ page, request }) => {
    // Get first published post
    const listResp = await request.get(`${WP_URL}/wp-json/wp/v2/posts?status=publish&per_page=1`);
    if (listResp.status() !== 200) {
      test.skip();
      return;
    }
    const posts = await listResp.json();
    if (!posts.length) {
      test.skip();
      return;
    }
    const postUrl = posts[0].link;
    await page.goto(postUrl);
    await page.waitForLoadState('domcontentloaded');

    // There may be multiple robots meta tags (WP default + ThinkRank).
    // Find the one that contains directive keywords — ThinkRank emits the full list.
    const allRobots = page.locator('meta[name="robots"]');
    const count = await allRobots.count();
    if (count > 0) {
      let foundIndexDirective = false;
      for (let i = 0; i < count; i++) {
        const content = await allRobots.nth(i).getAttribute('content');
        if (content && /index/i.test(content)) {
          foundIndexDirective = true;
          break;
        }
      }
      expect(foundIndexDirective).toBe(true);
    }
  });
});

// === METABOX: Open Graph Override fields ===
test.describe('Metabox — OG / Twitter meta keys', () => {
  let api;

  test.beforeAll(async () => {
    api = await createApiContext();
  });

  test.afterAll(async () => {
    await api.dispose();
  });

  test('REST write + read round-trip for _thinkrank_og_title on a post', async () => {
    // Get a post to test with
    const listResp = await api.get('/wp-json/wp/v2/posts?status=publish&per_page=1');
    if (listResp.status() !== 200) { return; }
    const posts = await listResp.json();
    if (!posts.length) { return; }

    const postId = posts[0].id;
    const testTitle = 'OG Title Test ' + Date.now();

    // Write via REST (meta must be show_in_rest: true)
    const writeResp = await api.post(`/wp-json/wp/v2/posts/${postId}`, {
      data: { meta: { _thinkrank_og_title: testTitle } },
    });
    // 200 if meta is properly registered in REST
    if (writeResp.status() === 200) {
      const readResp = await api.get(`/wp-json/wp/v2/posts/${postId}`);
      const postData = await readResp.json();
      expect(postData.meta?._thinkrank_og_title).toBe(testTitle);
    } else {
      // Meta may require nonce — still should not be 500
      expect(writeResp.status()).not.toBe(500);
    }
  });

  test('frontend og:title uses per-post override when set', async ({ page, request }) => {
    const listResp = await request.get(`${WP_URL}/wp-json/wp/v2/posts?status=publish&per_page=1`);
    if (listResp.status() !== 200) { return; }
    const posts = await listResp.json();
    if (!posts.length) { return; }

    await page.goto(posts[0].link);
    await page.waitForLoadState('domcontentloaded');

    // og:title should be present
    const ogTitle = page.locator('meta[property="og:title"]');
    const count = await ogTitle.count();
    expect(count).toBeGreaterThanOrEqual(1);
    if (count > 0) {
      const content = await ogTitle.getAttribute('content');
      expect(typeof content).toBe('string');
      expect(content.length).toBeGreaterThan(0);
    }
  });

  test('frontend og:description is present on singular post', async ({ page, request }) => {
    const listResp = await request.get(`${WP_URL}/wp-json/wp/v2/posts?status=publish&per_page=1`);
    if (listResp.status() !== 200) { return; }
    const posts = await listResp.json();
    if (!posts.length) { return; }

    await page.goto(posts[0].link);
    await page.waitForLoadState('domcontentloaded');

    const ogDesc = page.locator('meta[property="og:description"]');
    const count = await ogDesc.count();
    expect(count).toBeGreaterThanOrEqual(1);
  });
});

// === TWO-PHASE IMPORT: Full round-trip (yoast detect → export → snapshot → migrate) ===
test.describe('Two-phase import workflow — yoast end-to-end', () => {
  let api;

  test.beforeAll(async () => {
    api = await createApiContext();
  });

  test.afterAll(async () => {
    await api.dispose();
  });

  test('detect → export postmeta page 1 → snapshot exists → delete snapshot', async () => {
    // Step 1: Detect
    const detectResp = await api.get('/wp-json/thinkrank/v1/import/detect');
    expect(detectResp.status()).toBe(200);

    // Step 2: Export yoast postmeta page 1
    const exportResp = await api.post('/wp-json/thinkrank/v1/import/export', {
      data: { plugin: 'yoast', type: 'postmeta', page: 1, is_last_type: false },
    });
    expect(exportResp.status()).toBe(200);
    const exportBody = await exportResp.json();
    expect(['processing', 'complete']).toContain(exportBody.status);

    // Step 3: Snapshots list should reflect at least the manifest
    const snapshotsResp = await api.get('/wp-json/thinkrank/v1/import/snapshots');
    const snapshotsBody = await snapshotsResp.json();
    expect(snapshotsBody).toHaveProperty('snapshots');

    // Step 4: Clean up — delete the yoast snapshot
    const deleteResp = await api.delete('/wp-json/thinkrank/v1/import/snapshot', {
      data: { plugin: 'yoast' },
    });
    expect(deleteResp.status()).toBe(200);
    const deleteBody = await deleteResp.json();
    expect(deleteBody.status).toBe('complete');
  });

  test('migrate returns has_more:false and processed/skipped for settings type', async () => {
    // Export settings first to create a complete snapshot
    await api.post('/wp-json/thinkrank/v1/import/export', {
      data: { plugin: 'yoast', type: 'settings', page: 1, is_last_type: true },
    });

    // Then try to migrate
    const migrateResp = await api.post('/wp-json/thinkrank/v1/import/migrate', {
      data: { plugin: 'yoast', type: 'settings', page: 1, is_last_type: true },
    });
    expect(migrateResp.status()).toBe(200);
    const body = await migrateResp.json();
    expect(body).toHaveProperty('has_more');
    if (body.status !== 'error') {
      expect(body.has_more).toBe(false);
    }

    // Clean up
    await api.delete('/wp-json/thinkrank/v1/import/snapshot', {
      data: { plugin: 'yoast' },
    });
  });
});
